import chalk from "chalk";

//#region src/logger.ts
let currentPrompt = "";
let currentLine = "";
/**
* Set the current prompt for preservation during logging.
* This ensures the prompt is restored after log output.
*
* @param prompt - The prompt string (e.g., "> ")
* @param line - The current input line
*/
function setPrompt(prompt, line = "") {
	currentPrompt = prompt;
	currentLine = line;
}
/**
* Clear the current input line while preserving the prompt.
*/
function clearPromptLine() {
	currentLine = "";
}
function clearLine() {
	if (currentPrompt || currentLine) process.stdout.write("\r\x1B[K");
}
function restorePrompt() {
	if (currentPrompt || currentLine) process.stdout.write(currentPrompt + currentLine);
}
function logWithPrompt(...args) {
	clearLine();
	console.log(...args);
	restorePrompt();
}
const logger = {
	debug(...args) {
		logWithPrompt(...args);
	},
	log(...args) {
		logWithPrompt(...args);
	},
	info(...args) {
		logWithPrompt("ℹ️", ...args);
	},
	warn(...args) {
		logWithPrompt("⚠️", ...args);
	},
	error(...args) {
		logWithPrompt("🛑", ...args);
	},
	success(...args) {
		logWithPrompt("✅", ...args);
	},
	server(...args) {
		logWithPrompt(chalk.magenta("[SERVER]"), ...args);
	},
	client(id, ...args) {
		logWithPrompt(chalk.cyan(`[${id}]`), ...args);
	}
};
/**
* Create a logger instance for a specific client.
* Each method prefixes output with the client ID in a colored format.
*
* @param id - Client identifier
* @returns Logger instance with client-specific formatting
*/
function createClientLogger(id) {
	return {
		debug(...args) {
			logWithPrompt(chalk.gray(`[${id}]`), ...args);
		},
		log(...args) {
			logWithPrompt(chalk.cyan(`[${id}]`), ...args);
		},
		warn(...args) {
			logWithPrompt(chalk.yellow(`⚠️ [${id}]`), ...args);
		},
		error(...args) {
			logWithPrompt(chalk.red(`🛑 [${id}]`), ...args);
		}
	};
}

//#endregion
export { clearPromptLine, createClientLogger, logger, setPrompt };